import { relations } from "drizzle-orm";
import { boolean, date, index, integer, pgTable, text, timestamp, uniqueIndex, uuid } from "drizzle-orm/pg-core";
import { user } from "./auth-schema";

export * from "./auth-schema";

// Conventions:
// - UUID primary keys generated by the app, so a retried create is a no-op.
// - Money is whole taka as an integer.
// - Dates are Dhaka dates stored as `date` and handled as "YYYY-MM-DD" strings.
// - Every table has RLS enabled and no policies: the app connects as the table owner,
//   while the Supabase auto-generated API can read nothing.
// - Every row belongs to one ghotok (`ghotok_id` = Better Auth user id of the site's owner). A deployment is one
//   ghotok's website (the `site` row), but the column keeps the data of several ghotoks apart should one database
//   ever serve more than one site.

const id = () => uuid("id").primaryKey();
const day = (name: string) => date(name, { mode: "string" });
const timestamps = {
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow().$onUpdate(() => new Date()),
};

/* ---------- the site ---------- */

/**
 * The one row that makes this deployment a ghotok's website: whose it is and what the front page says. Created once
 * from /setup; until it exists every screen sends visitors there. `id` is always 1, so a second row cannot be inserted.
 */
export const site = pgTable("site", {
  id: integer("id").primaryKey().default(1),
  /** the ghotok who owns the site; every profile, proposal and ledger entry hangs off this id */
  ghotokId: text("ghotok_id").notNull().unique().references(() => user.id, { onDelete: "restrict" }),
  /** what the site is called, e.g. "করিম ঘটক ম্যারেজ মিডিয়া" */
  name: text("name").notNull(),
  /** one line under the name on the front page; null shows a stock line */
  tagline: text("tagline"),
  /** a paragraph about the ghotok; null shows stock text */
  about: text("about"),
  /** village, upazila, district, as the ghotok writes it */
  address: text("address"),
  /** 01XXXXXXXXX; null means the ghotok's login number */
  whatsapp: text("whatsapp"),
  ...timestamps,
}).enableRLS();

/* ---------- people ---------- */

export type ProfileKind = "patro" | "patri";
export type ProfileStatus = "active" | "engaged" | "married" | "inactive";
/**
 * Whether the ghotok has put this biodata in the lists. The ghotok's own entries are "approved" from the start; one a
 * family hands in waits as "pending", and is "returned" with a note when the ghotok wants it changed. Only approved
 * people are listed, counted, matched or proposed.
 */
export type Approval = "pending" | "approved" | "returned";
export type Religion = "islam" | "hindu" | "christian" | "buddhist" | "other";
export type MaritalStatus = "obibahito" | "talakprapto" | "bidhoba";
/* The optional, pick-one answers on the biodata form. Null everywhere means "would rather not say" / "any". */
export type Complexion = "forsha" | "ujjol_shyamla" | "shyamla" | "kalo";
export type BloodGroup = "A+" | "A-" | "B+" | "B-" | "O+" | "O-" | "AB+" | "AB-";
export type EducationMedium = "general" | "madrasa" | "english";
export type FamilyStatus = "nimno" | "moddho" | "uccho_moddho" | "uccho";
/** yes / no / to be discussed: the "after marriage" questions */
export type Choice = "yes" | "no" | "discuss";
/** where a groom means to live with his wife */
export type AfterHome = "family" | "city" | "abroad" | "undecided";
/** whether a groom's side expects anything from the bride's */
export type Dowry = "none" | "gift" | "discuss";
export type ExpectEducation = "ssc" | "hsc" | "bachelor" | "master";
export type ExpectMarital = "obibahito" | "talak_ok" | "bidhoba_ok";

/** A groom (patro) or bride (patri) the ghotok is looking for a match for. */
export const profile = pgTable("profile", {
  id: id(),
  ghotokId: text("ghotok_id").notNull().references(() => user.id, { onDelete: "cascade" }),
  kind: text("kind").$type<ProfileKind>().notNull(),
  /** the biodata number families are told: counts up from 1 per ghotok and kind ("পাত্র-১২"), set on insert */
  code: integer("code").notNull(),
  name: text("name").notNull(),
  fatherName: text("father_name"),
  motherName: text("mother_name"),
  /** exact birth dates are often unknown in villages; the year is enough for age */
  birthYear: integer("birth_year").notNull(),
  heightCm: integer("height_cm"),
  religion: text("religion").$type<Religion>().notNull().default("islam"),
  maritalStatus: text("marital_status").$type<MaritalStatus>().notNull().default("obibahito"),
  education: text("education"),
  profession: text("profession"),
  /** taka per month; null = not given */
  monthlyIncome: integer("monthly_income"),
  village: text("village"),
  upazila: text("upazila"),
  district: text("district").notNull(),
  guardianName: text("guardian_name"),
  /** 01XXXXXXXXX */
  guardianPhone: text("guardian_phone"),
  familyDetails: text("family_details"),
  /** what kind of match the family is looking for */
  expectations: text("expectations"),
  /* the looks and the papers families ask about first */
  complexion: text("complexion").$type<Complexion>(),
  weightKg: integer("weight_kg"),
  bloodGroup: text("blood_group").$type<BloodGroup>(),
  educationMedium: text("education_medium").$type<EducationMedium>(),
  /** where they work, or a line about the work */
  workplace: text("workplace"),
  /** town or country they live in now, when not the village (jobs, abroad); null = at home */
  presentAddress: text("present_address"),
  /* the family in numbers and a line on religious practice; the prose stays in familyDetails */
  brothers: integer("brothers"),
  sisters: integer("sisters"),
  familyStatus: text("family_status").$type<FamilyStatus>(),
  religiousPractice: text("religious_practice"),
  /* after marriage: a groom answers for his wife (may she study / work, where they will live, any dowry);
     a bride answers for herself (will she study / work, is a joint family fine) */
  afterStudy: text("after_study").$type<Choice>(),
  afterJob: text("after_job").$type<Choice>(),
  afterHome: text("after_home").$type<AfterHome>(),
  dowry: text("dowry").$type<Dowry>(),
  jointFamily: text("joint_family").$type<Choice>(),
  /* the match they hope for, in a form the suggestions can use; the prose stays in expectations */
  expectAgeMin: integer("expect_age_min"),
  expectAgeMax: integer("expect_age_max"),
  expectEducation: text("expect_education").$type<ExpectEducation>(),
  expectMarital: text("expect_marital").$type<ExpectMarital>(),
  /** districts that would suit, comma-separated as written; null = anywhere */
  expectDistricts: text("expect_districts"),
  /** when the family ticked "my guardian knows, and all of this is true"; null for the ghotok's own entries */
  pledgedAt: timestamp("pledged_at", { withTimezone: true }),
  /** when the ghotok approved a family's biodata; shown to other families as the ghotok's check */
  approvedAt: timestamp("approved_at", { withTimezone: true }),
  photoUrl: text("photo_url"),
  /** the family agrees to other families seeing the father's and mother's names; off by default, the ghotok can switch it */
  showParents: boolean("show_parents").notNull().default(false),
  /** the family agrees to other signed-in families seeing the photos (never on the public link); off by default */
  showPhotos: boolean("show_photos").notNull().default(false),
  /** the ghotok's private notes; a family never sees or edits these */
  notes: text("notes"),
  status: text("status").$type<ProfileStatus>().notNull().default("active"),
  /** the family account that wrote this biodata; null when the ghotok did */
  ownerUserId: text("owner_user_id").references(() => user.id, { onDelete: "set null" }),
  approval: text("approval").$type<Approval>().notNull().default("approved"),
  /** what the ghotok asked the family to change, shown to them while the biodata is "returned" */
  returnNote: text("return_note"),
  ...timestamps,
}, (t) => [
  index("profile_ghotok_kind_status").on(t.ghotokId, t.kind, t.status),
  index("profile_ghotok_approval").on(t.ghotokId, t.approval),
  index("profile_owner").on(t.ownerUserId),
  uniqueIndex("profile_ghotok_kind_code").on(t.ghotokId, t.kind, t.code),
]).enableRLS();

/**
 * A public, read-only biodata link the ghotok hands to a family: /b/<token>. The token is the only credential, so it
 * is random and long enough to guess at nobody. One link per person; deleting the row switches the link off.
 */
export const biodataShare = pgTable("biodata_share", {
  token: text("token").primaryKey(),
  ghotokId: text("ghotok_id").notNull().references(() => user.id, { onDelete: "cascade" }),
  profileId: uuid("profile_id").notNull().unique().references(() => profile.id, { onDelete: "cascade" }),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
}).enableRLS();

/**
 * A photo of a person: up to five each, the file in storage (Supabase Storage, or ./.data/photos in development) at
 * `path`. Private like the name: only the ghotok and the family who wrote the biodata see them, through
 * /api/photos/<id>. The first by `position` is the picture on the card.
 */
export const profilePhoto = pgTable("profile_photo", {
  id: uuid("id").primaryKey(),
  ghotokId: text("ghotok_id").notNull().references(() => user.id, { onDelete: "cascade" }),
  profileId: uuid("profile_id").notNull().references(() => profile.id, { onDelete: "cascade" }),
  /** where the file is in storage: <ghotokId>/<profileId>/<id>.jpg */
  path: text("path").notNull(),
  contentType: text("content_type").notNull(),
  /** 0 is the cover picture */
  position: integer("position").notNull().default(0),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
}, (t) => [index("profile_photo_profile").on(t.profileId, t.position)]).enableRLS();

/* ---------- proposals ---------- */

export type ProposalStatus = "prostab" | "dekha_shona" | "kotha_cholche" | "thik_hoyeche" | "biye_hoyeche" | "bad";

/** One patro put forward for one patri, and how far the talks have gone. */
export const proposal = pgTable("proposal", {
  id: id(),
  ghotokId: text("ghotok_id").notNull().references(() => user.id, { onDelete: "cascade" }),
  patroId: uuid("patro_id").notNull().references(() => profile.id, { onDelete: "cascade" }),
  patriId: uuid("patri_id").notNull().references(() => profile.id, { onDelete: "cascade" }),
  status: text("status").$type<ProposalStatus>().notNull().default("prostab"),
  note: text("note"),
  ...timestamps,
}, (t) => [
  uniqueIndex("proposal_pair").on(t.patroId, t.patriId),
  index("proposal_ghotok_status").on(t.ghotokId, t.status),
]).enableRLS();

export type ProposalEventKind = "created" | "status" | "note";

/** The timeline under a proposal: every status change and note, in order. */
export const proposalEvent = pgTable("proposal_event", {
  id: id(),
  proposalId: uuid("proposal_id").notNull().references(() => proposal.id, { onDelete: "cascade" }),
  kind: text("kind").$type<ProposalEventKind>().notNull(),
  fromStatus: text("from_status").$type<ProposalStatus>(),
  toStatus: text("to_status").$type<ProposalStatus>(),
  note: text("note"),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
}, (t) => [index("proposal_event_proposal").on(t.proposalId, t.createdAt)]).enableRLS();

/* ---------- money ---------- */

/** chukti = fee agreed with a family, joma = money received, khoroch = the ghotok's own expense */
export type LedgerKind = "chukti" | "joma" | "khoroch";

export const ledgerEntry = pgTable("ledger_entry", {
  id: id(),
  ghotokId: text("ghotok_id").notNull().references(() => user.id, { onDelete: "cascade" }),
  /** the match this money belongs to; null for general income or expenses */
  proposalId: uuid("proposal_id").references(() => proposal.id, { onDelete: "set null" }),
  kind: text("kind").$type<LedgerKind>().notNull(),
  /** whole taka, always positive; the kind says which way it goes */
  amount: integer("amount").notNull(),
  note: text("note"),
  entryDate: day("entry_date").notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
}, (t) => [index("ledger_ghotok_date").on(t.ghotokId, t.entryDate)]).enableRLS();

/* ---------- relations ---------- */

export const profileRelations = relations(profile, ({ many }) => ({
  asPatro: many(proposal, { relationName: "patro" }),
  asPatri: many(proposal, { relationName: "patri" }),
}));

export const proposalRelations = relations(proposal, ({ one, many }) => ({
  patro: one(profile, { fields: [proposal.patroId], references: [profile.id], relationName: "patro" }),
  patri: one(profile, { fields: [proposal.patriId], references: [profile.id], relationName: "patri" }),
  events: many(proposalEvent),
  ledger: many(ledgerEntry),
}));

export const proposalEventRelations = relations(proposalEvent, ({ one }) => ({
  proposal: one(proposal, { fields: [proposalEvent.proposalId], references: [proposal.id] }),
}));

export const ledgerEntryRelations = relations(ledgerEntry, ({ one }) => ({
  proposal: one(proposal, { fields: [ledgerEntry.proposalId], references: [proposal.id] }),
}));

export type Site = typeof site.$inferSelect;
export type Profile = typeof profile.$inferSelect;
export type Proposal = typeof proposal.$inferSelect;
export type ProposalEvent = typeof proposalEvent.$inferSelect;
export type LedgerEntry = typeof ledgerEntry.$inferSelect;
export type BiodataShare = typeof biodataShare.$inferSelect;
export type ProfilePhoto = typeof profilePhoto.$inferSelect;
